import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def feature_pairs(ctx):
    inputs = torch.randn(4, generator=ctx.rng.torch)
    teacher_features = torch.randn(3, generator=ctx.rng.torch)
    negative_teacher_features = torch.randn((2, 3), generator=ctx.rng.torch)
    return {"inputs": synth.Tensor(inputs), "teacher_features": synth.Tensor(teacher_features), "negative_teacher_features": synth.Tensor(negative_teacher_features)}
dataset = synth.Spec("crd-feature-pairs", generator=feature_pairs, size=8, splits={"train": 1.0}, seed=7, root=root, monitor="none").run()
train = dataset.for_recipe("structured-objective", split="train")
class Student(nn.Module):
    def __init__(self):
        super().__init__()
        self.projection = build("mlp", "tiny", in_features=4, out_features=3)
    def forward(self, inputs):
        return {"student_features": self.projection(inputs)}
trainer = Trainer(Student(), train, recipe="structured-objective", recipe_config={"loss": "crd", "loss_kwargs": {"dataset_size": 8, "num_negatives": 2}, "bindings": {"logits_or_prediction": {"output": "student_features"}, "targets": {"batch": "teacher_features"}, "negative_teacher_features": {"batch": "negative_teacher_features"}}}, batch_size=4, max_epochs=1, device="cpu")
trainer.fit()
